import java.util.*;

public class Main {
    public static void main(String[] args) {
        Todo t = new Todo(7, "Setor kas");
        System.out.println(t.isSelesai());
        t.selesaikan();
        t.selesaikan();
        System.out.println(t.isSelesai());
        System.out.println(t.getId() + " " + t.getJudul());
    }
}

class Todo {
    private final int id;
    private final String judul;
    private boolean selesai;

    Todo(int id, String judul) {
        this.id = id;
        this.judul = judul;
    }

    int getId() {
        return id;
    }

    String getJudul() {
        return judul;
    }

    boolean isSelesai() {
        return selesai;
    }

    void selesaikan() {
        selesai = true;
    }

    @Override
    public String toString() {
        return id + ". [" + (selesai ? "x" : " ") + "] " + judul;
    }
}

