import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String kata = in.nextLine();
        List<Todo> semua = new ArrayList<>();
        int id = 1;
        while (in.hasNextLine()) {
            semua.add(new Todo(id++, in.nextLine()));
        }
        int ketemu = 0;
        for (Todo t : semua) {
            if (t.cocok(kata)) {
                System.out.println(t);
                ketemu++;
            }
        }
        if (ketemu == 0) {
            System.out.println("Tidak ada");
        }
    }
}

class Todo {
    private final int id;
    private final String judul;
    private boolean selesai;

    Todo(int id, String judul) {
        this.id = id;
        this.judul = judul;
    }

    int getId() {
        return id;
    }

    String getJudul() {
        return judul;
    }

    boolean isSelesai() {
